from fractions import Fraction
def binary_round(x,precision):
 if x==0:return Fraction(0)
 if x<0:return -binary_round(-x,precision)
 n,d=x.numerator,x.denominator;e=n.bit_length()-d.bit_length()
 if (n<d*(1<<e) if e>=0 else n*(1<<(-e))<d):e-=1
 shift=precision-1-e
 scaled=x*(1<<shift) if shift>=0 else x/Fraction(1<<(-shift))
 q,r=divmod(scaled.numerator,scaled.denominator)
 if 2*r>scaled.denominator or (2*r==scaled.denominator and q&1):q+=1
 return Fraction(q,1<<shift) if shift>=0 else Fraction(q*(1<<(-shift)))
def expected_resistance(magic,paralysis,cw):
 if magic>=100 or paralysis>=100:return 0.
 precision={127:24,639:53,895:64}[cw];r=lambda x:binary_round(x,precision)
 a=binary_round(r(Fraction(magic)/100),24);b=binary_round(r(Fraction(paralysis)/100),24)
 return float(binary_round(r(1-r(a+r(r(1-a)*b))),24))

